done.script:
var pm = tree.root.get_node_or_null("/root/PhaseManager")
if pm == null or pm.current_phase_instance == null:
	return false
var phase = pm.current_phase_instance
if not phase.has_method("get_newly_drawn_missions"):
	return false
if phase.get_newly_drawn_missions().size() > 0:
	return false
return tree.root.get_node_or_null("/root/SecondaryMissionReviewDialog") == null

if tree.root.get_node_or_null("/root/GuardSelectionDialog") != null:
	return false
var smm = tree.root.get_node_or_null("/root/SecondaryMissionManager")
if smm == null:
	return false
for m in smm._player_state.get("1", {}).get("active", []):
	if m.get("pending_interaction", false):
		return false
return true
